from typing import List, Tuple
import itertools
from math import inf


def min_spanning_tree_mod_k(n: int, m: int, k: int, edges: List[Tuple[int, int, int]]) -> int:
    """ Given a weighted simple connected undirected graph with n vertices and m edges,
    find the minimum cost of a spanning tree where the cost is defined as the sum of 
    edge weights modulo k.

    Args:
        n: Number of vertices (2 <= n <= 8)
        m: Number of edges (n-1 <= m <= n*(n-1)/2)
        k: Modulo value (1 <= k <= 10^15)
        edges: List of tuples (u, v, w) where u and v are vertices (1-indexed) and w is the weight
               - 1 <= u < v <= n
               - 0 <= w < k

    Returns:
        The minimum cost of a spanning tree modulo k
    """

    def union_find_parent(parent, x):
        if parent[x] != x:
            parent[x] = union_find_parent(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        rx, ry = union_find_parent(parent, x), union_find_parent(parent, y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    def is_spanning_tree(selected_edges, n):
        parent = list(range(n + 1))
        rank = [0] * (n + 1)
        count = 0
        for u, v, _ in selected_edges:
            if union(parent, rank, u, v):
                count += 1
        return count == n - 1

    def is_connected(selected_edges, n):
        if len(selected_edges) != n - 1:
            return False
        parent = list(range(n + 1))
        rank = [0] * (n + 1)
        count = 0
        for u, v, _ in selected_edges:
            if union(parent, rank, u, v):
                count += 1
        return count == n - 1

    # Since n is small (up to 8), the number of spanning trees is manageable.
    # We can iterate over all combinations of n-1 edges from m edges.
    # Check if they form a spanning tree, then compute sum % k and track minimum.

    min_mod = k  # Initialize with a value larger than any possible mod result

    # Total number of ways to choose n-1 edges from m
    if m < n - 1:
        return -1  # Should not happen per constraints (graph is connected)

    edges_list = list(edges)

    for combo in itertools.combinations(edges_list, n - 1):
        if is_connected(combo, n):
            total = sum(w for _, _, w in combo)
            mod_val = total % k
            if mod_val < min_mod:
                min_mod = mod_val
                if min_mod == 0:
                    break  # Cannot get lower than 0

    return min_mod
